export interface GitOperatorReviewPayloadV1 {
  reviewVersion: 1;
  audience: string;
  operatorId: string;
  keyId: Digest;
  decision: "approve" | "deny";
  proposalId: Digest;
  authorityDigest: Digest;
  effectDigest: Digest;
