  operators: {
    operatorId: string;
    enabled: boolean;
    keys: { keyId: Digest; publicKeyPem: string; enabled: boolean }[];
    permissions: {
      repositoryId: string;
      workspaceRootDigest: Digest;
      destinationRef: string;
