const DOMAIN = "ReproGate/GitOperatorReview/v1\0";
const SIGNATURE_PATTERN = /^[A-Za-z0-9_-]{85}[AQgw]$(?![\s\S])/u;
const PUBLIC_PEM_PATTERN =
