import { createHmac, randomUUID, timingSafeEqual } from "node:crypto";

import { canonicalJson } from "./canonical-json.js";
import type { Digest } from "./types.js";

export interface CapabilityClaimsV1 {
  version: 1;
  jti: string;
  actionId: Digest;
  envelopeDigest: Digest;
  scopes: string[];
  issuedAt: string;
  expiresAt: string;
}

export interface CapabilityBinding {
  actionId: Digest;
  envelopeDigest: Digest;
  requiredScopes: string[];
}

export interface TokenUseStore {
  consume(jti: string): boolean;
}

export class InMemoryTokenUseStore implements TokenUseStore {
  readonly #used = new Set<string>();

  consume(jti: string): boolean {
    if (this.#used.has(jti)) return false;
    this.#used.add(jti);
    return true;
  }
}

function keyBytes(secret: string | Uint8Array): Uint8Array {
  const bytes = typeof secret === "string" ? Buffer.from(secret) : secret;
  if (bytes.byteLength < 32) {
    throw new Error("Capability signing secret must contain at least 32 bytes");
  }
  return bytes;
}

function signature(payload: string, secret: Uint8Array): Buffer {
  return createHmac("sha256", secret).update(payload).digest();
}

function validateClaims(value: unknown): CapabilityClaimsV1 {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("Invalid capability token claims");
  }
  const claims = value as Partial<CapabilityClaimsV1>;
  const digestPattern = /^sha256:[0-9a-f]{64}$/u;
  if (
    claims.version !== 1 ||
    typeof claims.jti !== "string" ||
    claims.jti.length === 0 ||
    typeof claims.actionId !== "string" ||
    !digestPattern.test(claims.actionId) ||
    typeof claims.envelopeDigest !== "string" ||
    !digestPattern.test(claims.envelopeDigest) ||
    !Array.isArray(claims.scopes) ||
    !claims.scopes.every((scope) => typeof scope === "string") ||
    typeof claims.issuedAt !== "string" ||
    typeof claims.expiresAt !== "string"
  ) {
    throw new Error("Invalid capability token claims");
  }
  const issuedAt = Date.parse(claims.issuedAt);
  const expiresAt = Date.parse(claims.expiresAt);
  if (!Number.isFinite(issuedAt) || !Number.isFinite(expiresAt)) {
    throw new Error("Invalid capability token timestamps");
  }
  if (expiresAt <= issuedAt) {
    throw new Error("Capability token must expire after it is issued");
  }
  return claims as CapabilityClaimsV1;
}

export function issueCapabilityToken(
  input: Omit<CapabilityClaimsV1, "version" | "jti" | "issuedAt"> & {
    issuedAt?: string;
    jti?: string;
  },
  secret: string | Uint8Array,
): string {
  const claims: CapabilityClaimsV1 = {
    version: 1,
    jti: input.jti ?? randomUUID(),
    actionId: input.actionId,
    envelopeDigest: input.envelopeDigest,
    scopes: [...new Set(input.scopes)].sort(),
    issuedAt: input.issuedAt ?? new Date().toISOString(),
    expiresAt: input.expiresAt,
  };
  validateClaims(claims);
  const payload = Buffer.from(canonicalJson(claims)).toString("base64url");
  const mac = signature(payload, keyBytes(secret)).toString("base64url");
  return `rg1.${payload}.${mac}`;
}

export function verifyCapabilityToken(
  token: string,
  binding: CapabilityBinding,
  secret: string | Uint8Array,
  now = new Date(),
): CapabilityClaimsV1 {
  const parts = token.split(".");
  if (parts.length !== 3 || parts[0] !== "rg1") {
    throw new Error("Malformed capability token");
  }
  const payload = parts[1];
  const encodedMac = parts[2];
  if (payload === undefined || encodedMac === undefined) {
    throw new Error("Malformed capability token");
  }

  const received = Buffer.from(encodedMac, "base64url");
  const expected = signature(payload, keyBytes(secret));
  if (
    received.byteLength !== expected.byteLength ||
    !timingSafeEqual(received, expected)
  ) {
    throw new Error("Invalid capability token signature");
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(Buffer.from(payload, "base64url").toString("utf8"));
  } catch {
    throw new Error("Invalid capability token payload");
  }

  const claims = validateClaims(parsed);

  if (claims.actionId !== binding.actionId) {
    throw new Error("Capability token is bound to a different action");
  }
  if (claims.envelopeDigest !== binding.envelopeDigest) {
    throw new Error("Capability token is bound to a different envelope");
  }
  if (!Number.isFinite(now.getTime())) {
    throw new Error("Verification time is invalid");
  }
  if (Date.parse(claims.expiresAt) <= now.getTime()) {
    throw new Error("Capability token has expired");
  }
  if (Date.parse(claims.issuedAt) > now.getTime()) {
    throw new Error("Capability token was issued in the future");
  }

  const grantedScopes = new Set(claims.scopes);
  if (binding.requiredScopes.some((scope) => !grantedScopes.has(scope))) {
    throw new Error("Capability token does not grant all required scopes");
  }
  return claims;
}

export function verifyAndConsumeCapabilityToken(
  token: string,
  binding: CapabilityBinding,
  secret: string | Uint8Array,
  useStore: TokenUseStore,
  now = new Date(),
): CapabilityClaimsV1 {
  const claims = verifyCapabilityToken(token, binding, secret, now);
  if (!useStore.consume(claims.jti)) {
    throw new Error("Capability token has already been consumed");
  }
  return claims;
}

#!/usr/bin/env node
import { readFileSync } from "node:fs";

import { serveStdio } from "@modelcontextprotocol/server/stdio";

import { issueCapabilityToken } from "./capability-token.js";
import { SqliteExecutionStore } from "./execution-store.js";
import { runGitReviewCli } from "./git-review-cli.js";
import { createHandoffService, type HandoffService } from "./handoff.js";
import {
  loadHandoffConfig,
  prepareHandoffDatabase,
  sameHandoffDatabase,
} from "./handoff-filesystem.js";
import { verifyExecutionReceipt } from "./receipt.js";
import {
  createConfiguredRuntime,
  loadRuntimeConfig,
} from "./runtime-config.js";
import { createDemoKernel, createReproGateServer } from "./server.js";

function requiredEnvironment(name: string): string {
  const value = process.env[name];
  if (value === undefined || value.length === 0) {
    throw new Error(`${name} must be set`);
  }
  return value;
}

function approve(
  databasePath: string,
  actionId: string,
  secretEnvironmentName: string,
): void {
  const store = new SqliteExecutionStore(databasePath);
  try {
    const plan = store.get(actionId);
    if (plan === undefined) throw new Error(`Unknown actionId: ${actionId}`);
    if (plan.policy.decision === "deny") {
      throw new Error("Denied action plans cannot be approved");
    }
    const now = new Date();
    if (Date.parse(plan.envelope.expiresAt) <= now.getTime()) {
      throw new Error("Cannot approve an expired action plan");
    }
    process.stdout.write(
      `${issueCapabilityToken(
        {
          actionId: plan.envelope.actionId,
          envelopeDigest: plan.envelopeDigest,
          scopes: plan.envelope.authority.scopes,
          expiresAt: plan.envelope.expiresAt,
          issuedAt: now.toISOString(),
        },
        requiredEnvironment(secretEnvironmentName),
      )}\n`,
    );
  } finally {
    store.close();
  }
}

function verifyReceiptFile(
  receiptPath: string,
  secretEnvironmentName: string,
  expectedKeyId?: string,
): void {
  const receipt: unknown = JSON.parse(readFileSync(receiptPath, "utf8"));
  const signingKeyId =
    receipt !== null &&
    typeof receipt === "object" &&
    "signingKeyId" in receipt &&
    typeof receipt.signingKeyId === "string"
      ? receipt.signingKeyId
      : undefined;
  const valid =
    (expectedKeyId === undefined || signingKeyId === expectedKeyId) &&
    verifyExecutionReceipt(receipt, requiredEnvironment(secretEnvironmentName));
  process.stdout.write(`${JSON.stringify({ valid, receipt })}\n`);
  if (!valid) process.exitCode = 1;
}

async function main(): Promise<void> {
  const command = process.argv[2] ?? "serve";
  if (command === "serve") {
    const usage =
      "Usage: reprogate serve [--config <absolute-path>] [--handoff-config <absolute-path>]";
    const options = new Map<string, string>();
    const rest = process.argv.slice(3);
    for (let index = 0; index < rest.length; index += 2) {
      const option = rest[index];
      const value = rest[index + 1];
      if (
        (option !== "--config" && option !== "--handoff-config") ||
        value === undefined ||
        options.has(option)
      )
        throw new Error(usage);
      options.set(option, value);
    }
    const configPath = options.get("--config");
    const handoffConfigPath = options.get("--handoff-config");
    const handoffConfig =
      handoffConfigPath === undefined
        ? undefined
        : loadHandoffConfig(handoffConfigPath);
    // Share the runtime connection only for the same physical database, so
    // plan references resolve against the plans this server records. Prepare
    // the private database file before the runtime's SQLite connection
    // could create it with default permissions.
    const shareDatabase =
      handoffConfig !== undefined &&
      configPath !== undefined &&
      sameHandoffDatabase(
        handoffConfig.databasePath,
        loadRuntimeConfig(configPath).databasePath,
      );
    if (shareDatabase) prepareHandoffDatabase(handoffConfig.databasePath);
    const runtime =
      configPath === undefined
        ? undefined
        : await createConfiguredRuntime(configPath);
    let handoff: HandoffService | undefined;
    try {
      if (handoffConfig !== undefined) {
        handoff = createHandoffService(handoffConfig, {
          ...(shareDatabase && runtime !== undefined
            ? { store: runtime.store }
            : {}),
        });
      }
    } catch (error) {
      runtime?.close();
      throw error;
    }
    if (runtime !== undefined && runtime.recoveredExecutions > 0) {
      process.stderr.write(
        `Recovered ${String(runtime.recoveredExecutions)} incomplete execution(s) as indeterminate\n`,
      );
    }
    const handle = serveStdio(
      () =>
        createReproGateServer(
          runtime?.kernel ?? createDemoKernel(),
          runtime?.executor,
          handoff,
          runtime?.mediator,
        ),
      {
        onerror: (error) => {
          process.stderr.write(`MCP transport error: ${error.message}\n`);
        },
      },
    );
    let closed = false;
    const closeResources = (): void => {
      if (closed) return;
      closed = true;
      handoff?.close();
      runtime?.close();
    };
    let closing = false;
    const shutdown = (): void => {
      if (closing) return;
      closing = true;
      void handle.close().finally(closeResources);
    };
    process.once("SIGINT", shutdown);
    process.once("SIGTERM", shutdown);
    process.once("exit", closeResources);
    return;
  }
  if (command === "demo") {
    const gate = createDemoKernel();
    const read = gate.plan({
      toolRef: "demo.read_file",
      arguments: { path: "README.md" },
      runId: "demo-read",
      now: new Date("2026-09-07T00:00:00.000Z"),
    });
    const publish = gate.plan({
      toolRef: "demo.publish",
      arguments: { content: "example" },
      runId: "demo-publish",
      now: new Date("2026-09-07T00:00:00.000Z"),
    });
    process.stdout.write(
      `${JSON.stringify(
        {
          note: "Phase 1 plans and binds actions; it does not execute them.",
          read: {
            actionId: read.envelope.actionId,
            decision: read.policy.decision,
          },
          publish: {
            actionId: publish.envelope.actionId,
            decision: publish.policy.decision,
            reasons: publish.policy.reasons,
          },
        },
        null,
        2,
      )}\n`,
    );
    return;
  }
  if (command === "approve") {
    if (process.argv[3] === "--config") {
      const configPath = process.argv[4];
      const actionId = process.argv[5];
      if (configPath === undefined || actionId === undefined) {
        throw new Error(
          "Usage: reprogate approve --config <absolute-path> <action-id>",
        );
      }
      const config = loadRuntimeConfig(configPath);
      approve(
        config.databasePath,
        actionId,
        config.secrets.capabilitySecretEnv,
      );
      return;
    }
    const databasePath = process.argv[3];
    const actionId = process.argv[4];
    if (databasePath === undefined || actionId === undefined) {
      throw new Error(
        "Usage: reprogate approve [--config <absolute-path> <action-id>|<database> <action-id>]",
      );
    }
    approve(databasePath, actionId, "REPROGATE_CAPABILITY_SECRET");
    return;
  }
  if (command === "verify-receipt") {
    if (process.argv[3] === "--config") {
      const configPath = process.argv[4];
      const receiptPath = process.argv[5];
      if (configPath === undefined || receiptPath === undefined) {
        throw new Error(
          "Usage: reprogate verify-receipt --config <absolute-path> <receipt.json>",
        );
      }
      const config = loadRuntimeConfig(configPath);
      verifyReceiptFile(
        receiptPath,
        config.secrets.receiptSecretEnv,
        config.secrets.receiptKeyId,
      );
      return;
    }
    const receiptPath = process.argv[3];
    if (receiptPath === undefined) {
      throw new Error("Usage: reprogate verify-receipt <receipt.json>");
    }
    verifyReceiptFile(receiptPath, "REPROGATE_RECEIPT_SECRET");
    return;
  }
  if (command === "git-review") {
    process.exitCode = runGitReviewCli(process.argv.slice(3), {
      stdout: (text) => process.stdout.write(text),
      stderr: (text) => process.stderr.write(text),
    });
    return;
  }
  process.stderr.write(
    "Usage: reprogate [serve [--config <absolute-path>] [--handoff-config <absolute-path>]|demo|approve [--config <absolute-path>] <target> <action-id>|verify-receipt [--config <absolute-path>] <receipt.json>|git-review <prepare|sign|import|check|revoke> ...]\n",
  );
  process.exitCode = 2;
}

void main().catch((error: unknown) => {
  process.stderr.write(
    `${error instanceof Error ? error.message : "Unknown command error"}\n`,
  );
  process.exitCode = 1;
});

import * as z from "zod/v4";

import { issueCapabilityToken } from "./capability-token.js";
import type { ReproGateExecutor } from "./executor.js";
import type { ReproGateKernel } from "./kernel.js";
import type { EffectClass } from "./types.js";

export const MEDIATED_EFFECTS = ["local_read", "network_read"] as const;
export const DEFAULT_MAX_TEXT_BYTES = 16 * 1024;
export const MAX_TEXT_BYTES = 256 * 1024;
export const MAX_RUNS_PER_PLAN = 1000;
export const REDACTED = "[REDACTED]";
/** Secret fragments at least this long are redacted wherever they appear. */
export const SECRET_FRAGMENT_LENGTH = 12;
const MAX_ERROR_BYTES = 1024;

// Capability tokens have this shape; a downstream echo must never reach
// the model, whichever secret signed it.
const CAPABILITY_TOKEN = /rg1\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/gu;

// A usable pattern compiles and cannot match the empty string, which would
// otherwise insert a marker between every character.
function usablePattern(pattern: string): boolean {
  try {
    return !new RegExp(pattern, "u").test("");
  } catch {
    return false;
  }
}

export const mediationConfigSchema = z
  .object({
    effects: z
      .array(z.enum(MEDIATED_EFFECTS))
      .min(1)
      .refine((effects) => new Set(effects).size === effects.length),
    maxRunsPerPlan: z.number().int().min(1).max(MAX_RUNS_PER_PLAN).optional(),
    result: z
      .object({
        maxTextBytes: z.number().int().min(256).max(MAX_TEXT_BYTES).optional(),
        redactPatterns: z
          .array(z.string().min(1).max(256).refine(usablePattern))
          .max(16)
          .optional(),
      })
      .strict()
      .optional(),
  })
  .strict();

export type MediationConfigV1 = z.infer<typeof mediationConfigSchema>;

export type MediationRefusal =
  | "unknown_action"
  | "not_allowed"
  | "effect_not_mediated"
  | "stale_plan"
  | "expired"
  | "run_limit";

export class MediationError extends Error {
  constructor(readonly code: MediationRefusal) {
    super(`Host mediation refused: ${code}`);
    this.name = "MediationError";
  }
}

export interface BoundedContent {
  content: { type: "text"; text: string }[];
  truncated: boolean;
  redactions: number;
  omittedItems: number;
}

export interface MediatedRunResult extends BoundedContent {
  executionId: string;
  outcome: "succeeded" | "failed";
  receiptDigest: string;
  resultDigest: string;
}

// Cut at a UTF-8 boundary so the bound never splits a character.
function truncateUtf8(text: string, maxBytes: number): string {
  const bytes = Buffer.from(text);
  if (bytes.length <= maxBytes) return text;
  let end = maxBytes;
  while (end > 0 && ((bytes[end] ?? 0) & 0xc0) === 0x80) end--;
  return bytes.subarray(0, end).toString("utf8");
}

// Every window of SECRET_FRAGMENT_LENGTH characters of each secret, in its
// raw and JSON-escaped spelling, so partial, split or escaped copies are
// caught. Shorter fragments cannot be distinguished from ordinary text.
function secretFragments(secrets: readonly string[]): string[] {
  const fragments = new Set<string>();
  for (const secret of secrets) {
    for (const form of [secret, JSON.stringify(secret).slice(1, -1)]) {
      if (form.length <= SECRET_FRAGMENT_LENGTH) {
        if (form.length > 0) fragments.add(form);
        continue;
      }
      for (
        let start = 0;
        start + SECRET_FRAGMENT_LENGTH <= form.length;
        start++
      )
        fragments.add(form.slice(start, start + SECRET_FRAGMENT_LENGTH));
    }
  }
  return [...fragments];
}

/**
 * Executes allow-decided, read-effect plans with a host-issued capability,
 * so the model never handles a token. Every executor check, the write-ahead
 * record and the signed receipt still apply.
 */
export class HostMediator {
  readonly #effects: ReadonlySet<EffectClass>;
  readonly #maxRuns: number;
  readonly #maxTextBytes: number;
  readonly #patterns: RegExp[];
  readonly #fragments: string[];
  readonly #slack: number;

  constructor(
    readonly executor: ReproGateExecutor,
    readonly kernel: ReproGateKernel,
    readonly config: MediationConfigV1,
    readonly capabilitySecret: string,
    receiptSecret: string,
    readonly clock: () => Date = () => new Date(),
  ) {
    this.#effects = new Set(config.effects);
    this.#maxRuns = config.maxRunsPerPlan ?? 1;
    this.#maxTextBytes = config.result?.maxTextBytes ?? DEFAULT_MAX_TEXT_BYTES;
    this.#patterns = (config.result?.redactPatterns ?? []).map(
      (pattern) => new RegExp(pattern, "gu"),
    );
    const secrets = [capabilitySecret, receiptSecret];
    this.#fragments = secretFragments(secrets);
    // Redact a little past the byte budget so a secret straddling the cut is
    // still recognised in full before the cut is applied.
    this.#slack =
      512 +
      2 * Math.max(...secrets.map((secret) => JSON.stringify(secret).length));
  }

  get mediatesNetwork(): boolean {
    return this.#effects.has("network_read");
  }

  async run(input: {
    actionId: string;
    arguments: Record<string, unknown>;
    now?: Date;
  }): Promise<MediatedRunResult> {
    const plan = this.executor.store.get(input.actionId);
    if (plan === undefined) throw new MediationError("unknown_action");
    if (plan.policy.decision !== "allow")
      throw new MediationError("not_allowed");
    // An effect-less plan declares nothing to allowlist; never mediate it.
    const effects = plan.envelope.authority.effects;
    if (
      effects.length === 0 ||
      !effects.every((effect) => this.#effects.has(effect))
    )
      throw new MediationError("effect_not_mediated");
    // Policy or catalog changes since planning withdraw mediation at once.
    if (this.kernel.currentDecision(plan.envelope) !== "allow")
      throw new MediationError("stale_plan");
    const now = input.now ?? this.clock();
    if (Date.parse(plan.envelope.expiresAt) <= now.getTime())
      throw new MediationError("expired");
    // Run numbers make the limit atomic: the store accepts each capability
    // ID once, so concurrent runs cannot both take the same slot.
    const prefix = `host-mediated:${plan.envelope.actionId.slice(7)}:`;
    let executed: Awaited<ReturnType<ReproGateExecutor["execute"]>> | undefined;
    // A concurrent run that took this slot first moves us to the next one.
    for (
      let run = this.executor.store.countCapabilityUses(prefix) + 1;
      run <= this.#maxRuns && executed === undefined;
      run++
    ) {
      const capabilityToken = issueCapabilityToken(
        {
          jti: `${prefix}${String(run)}`,
          actionId: plan.envelope.actionId,
          envelopeDigest: plan.envelopeDigest,
          scopes: plan.envelope.authority.scopes,
          issuedAt: now.toISOString(),
          expiresAt: plan.envelope.expiresAt,
        },
        this.capabilitySecret,
      );
      try {
        executed = await this.executor.execute({
          actionId: input.actionId,
          arguments: input.arguments,
          capabilityToken,
          now,
        });
      } catch (error) {
        if (!(
          error instanceof Error &&
          error.message === "Capability token has already been consumed"
        ))
          throw error;
      }
    }
    if (executed === undefined) throw new MediationError("run_limit");
    const { receipt, downstreamResult } = executed;
    return {
      executionId: receipt.executionId,
      outcome: receipt.outcome,
      receiptDigest: receipt.receiptDigest,
      resultDigest: receipt.resultDigest,
      ...this.bound(downstreamResult),
    };
  }

  /** A model-visible error message, redacted and bounded like results. */
  redactMessage(message: string): string {
    return truncateUtf8(
      this.#redact(message.slice(0, MAX_ERROR_BYTES * 2)).text,
      MAX_ERROR_BYTES,
    );
  }

  #redact(text: string): { text: string; count: number } {
    const ranges: [number, number][] = [];
    for (const fragment of this.#fragments) {
      for (
        let index = text.indexOf(fragment);
        index !== -1;
        index = text.indexOf(fragment, index + 1)
      )
        ranges.push([index, index + fragment.length]);
    }
    // Overlapping or adjacent fragment matches form one redacted span.
    ranges.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
    const spans: [number, number][] = [];
    for (const [start, end] of ranges) {
      const last = spans.at(-1);
      if (last !== undefined && start <= last[1])
        last[1] = Math.max(last[1], end);
      else spans.push([start, end]);
    }
    let count = spans.length;
    let value = "";
    let cursor = 0;
    for (const [start, end] of spans) {
      value += `${text.slice(cursor, start)}${REDACTED}`;
      cursor = end;
    }
    value += text.slice(cursor);
    for (const pattern of [CAPABILITY_TOKEN, ...this.#patterns]) {
      value = value.replace(pattern, () => {
        count++;
        return REDACTED;
      });
    }
    return { text: value, count };
  }

  /** Redact, then bound, the model-visible view of a downstream result. */
  bound(result: unknown): BoundedContent {
    const texts: string[] = [];
    let omittedItems = 0;
    const shaped =
      result !== null && typeof result === "object" && "content" in result;
    if (shaped && Array.isArray(result.content)) {
      for (const item of result.content as unknown[]) {
        if (
          item !== null &&
          typeof item === "object" &&
          "type" in item &&
          item.type === "text" &&
          "text" in item &&
          typeof item.text === "string"
        )
          texts.push(item.text);
        else omittedItems++;
      }
      if (
        "structuredContent" in result &&
        result.structuredContent !== undefined
      )
        texts.push(JSON.stringify(result.structuredContent));
    } else if (result !== undefined) {
      texts.push(JSON.stringify(result));
    }

    let remaining = this.#maxTextBytes;
    let truncated = false;
    let redactions = 0;
    const content: { type: "text"; text: string }[] = [];
    for (const text of texts) {
      if (remaining <= 0) {
        truncated = true;
        break;
      }
      // Characters past remaining + slack can never be shown.
      const window = text.slice(0, remaining + this.#slack);
      const redacted = this.#redact(window);
      redactions += redacted.count;
      // A window cut mid-secret could end in a fragment too short to
      // recognise; never show the characters just before such a cut.
      const shown =
        window.length === text.length
          ? redacted.text
          : redacted.text.slice(0, -(SECRET_FRAGMENT_LENGTH - 1));
      const bounded = truncateUtf8(shown, remaining);
      content.push({ type: "text", text: bounded });
      remaining -= Buffer.byteLength(bounded);
