    const { approvalId, context, trust } = input;
    const authority = deriveGitApprovalAuthorityFromPlan(proposal, context);
    return store.matchesOperatorReviewedApproval({
      approvalId,
      proposal,
      repositoryPath: context.repositoryPath,
      patch,
